effect.shader:
float smoothstepRev(float edge0, float edge1, float x) {
if(edge0 == edge1) return step(edge0, x);
else return smoothstep(edge0, edge1, x);
}
void main(){
vec2 uv = acScreenNorm;
float adjStart = start;
float adjEnd = end;
float adjFeather = feather/100.0;
float rad = angle * 0.0174533;
vec2 v = normalize(vec2(cos(rad), -sin(rad)));
float p = dot(acLayerNorm.st - vec2(0.5, 0.5), v) + 0.5;
float p0 = smoothstepRev(adjStart - adjFeather, adjStart, p);
float p1 = 1.0 - smoothstepRev(adjEnd, adjEnd + adjFeather, p);
float mask = clamp(p0 * p1, 0.0, 1.0);
vec4 texColor = texture2DCv(inputImg.texture, uv);
vec4 result;
if( blendMode==1 ) {
result = vec4((texColor.rgb/texColor.a) * fillColor.rgb, 1.0) * texColor.a;
} else if( blendMode==2 ) {
result = vec4(1.0 - ((1.0 - (texColor.rgb/texColor.a)) * (1.0 - fillColor.rgb)), 1.0) * texColor.a;
} else {
result = vec4(fillColor.rgb, 1.0) * texColor.a;
}
gl_FragColor = mix(texColor, result, alpha * mask);
}
